test('descarta callback tardio após fechar e trocar de BU, e reusa a intenção após perda de resposta sem duplicar BU', async ({ page, request, context }) => {
  const seed = await newActor(request);
  await installSdkDouble(page);
  await signIn(context, page, seed.tenantA.owner);
  let reservationRequests = 0;
  const reservationKeys: string[] = [];
  const reservationBodies: string[] = [];
  let lostFirstResponse = false;
  let firstAttemptId: string | undefined;
  let replayObservation: ReplayObservation | undefined;
  let replayVisibleCopy: string[] = [];
  page.on('request', (requestEvent) => {
    if (requestEvent.method() === 'POST' && new URL(requestEvent.url()).pathname === '/api/bff/number-registrations') {
      reservationRequests += 1;
      reservationKeys.push(requestEvent.headers()['idempotency-key'] ?? '');
      reservationBodies.push(requestEvent.postData() ?? '');
    }
  });
  let authorizeRequests = 0;
  page.on('request', (requestEvent) => {
    if (requestEvent.method() === 'POST' && /\/number-registrations\/[^/]+\/authorize$/.test(new URL(requestEvent.url()).pathname)) authorizeRequests += 1;
  });
  await page.getByRole('button', { name: 'Iniciar cadastro' }).click();
  await page.getByLabel('Business Unit').selectOption('__nova__');
  await page.getByLabel('Nome da nova Business Unit').fill('BU com resposta perdida');
  await page.route((url) => url.origin === new URL(page.url()).origin && url.pathname === '/api/bff/number-registrations', async (route) => {
    if (route.request().method() !== 'POST') return route.continue();
    const realResponse = await route.fetch();
    const parsed = JSON.parse((await realResponse.body()).toString()) as Record<string, unknown>;
    const attempt = parsed.attempt && typeof parsed.attempt === 'object' ? parsed.attempt as Record<string, unknown> : null;
    if (!lostFirstResponse) {
      lostFirstResponse = true;
      firstAttemptId = typeof attempt?.id === 'string' ? attempt.id : undefined;
      await route.abort('failed');
      return;
    }
    replayObservation = {
      status: realResponse.status(),
      hasAttempt: Boolean(attempt),
      sameAttempt: typeof attempt?.id === 'string' && firstAttemptId ? attempt.id === firstAttemptId : null,
      hasNonce: typeof parsed.nonce === 'string' && parsed.nonce.length > 0,
      replay: parsed.replay === true,
      state: typeof attempt?.state === 'string' ? attempt.state : null,
      stage: typeof attempt?.stage === 'string' ? attempt.stage : null,
      version: typeof attempt?.version === 'number' ? attempt.version : null,
      errorCode: typeof parsed.code === 'string' && /^[A-Z0-9_]{1,80}$/.test(parsed.code) ? parsed.code : null,
    };
    await route.fulfill({ response: realResponse });
  });
  const before = await context.request.get(`${API}/api/bff/business-units`);
  expect(before.ok()).toBeTruthy();
  const beforeUnits = (await before.json() as UnitList).businessUnits.length;
  await page.getByRole('button', { name: 'Reservar tentativa' }).click();
  await expect.poll(() => reservationRequests).toBe(1);
  await expect(page.getByRole('alert')).toBeVisible();
  await page.getByRole('button', { name: 'Reservar tentativa' }).click();
  await expect.poll(() => replayObservation !== undefined).toBe(true);
  expect(reservationKeys[1]).toBe(reservationKeys[0]);
  expect(reservationBodies[1]).toBe(reservationBodies[0]);
  replayVisibleCopy = await page.locator('[role="alert"], [role="status"]').allTextContents();
  console.log('[REPLAY-EVIDENCE] ' + JSON.stringify({ ...replayObservation, visibleCopy: replayVisibleCopy }));
  expect(replayObservation).toMatchObject({ status: 201, hasAttempt: true, sameAttempt: true, hasNonce: true, replay: true, state: 'PENDING_AUTH' });
  await expect(page.getByRole('button', { name: 'Ignorar resposta desta janela' })).toHaveCount(0);
  await expect(page.getByRole('button', { name: 'Continuar com a Meta' })).toBeEnabled();
  expect(reservationRequests).toBe(2);
  expect(reservationKeys[0]).toBeTruthy();
  expect(reservationKeys[1]).toBe(reservationKeys[0]);
  expect(reservationBodies[1]).toBe(reservationBodies[0]);
  const after = await context.request.get(`${API}/api/bff/business-units`);
  expect(after.ok()).toBeTruthy();
  expect((await after.json() as UnitList).businessUnits).toHaveLength(beforeUnits + 1);

  await page.getByRole('button', { name: 'Cancelar tentativa' }).click();
  await expect(page.getByRole('status').filter({ hasText: 'Tentativa encerrada antes de efeitos externos' })).toBeVisible();
  await page.getByRole('button', { name: 'Iniciar nova autorização para esta Business Unit' }).click();
  await page.getByRole('button', { name: 'Reservar tentativa' }).click();
  await expect.poll(() => reservationRequests).toBe(3);
  expect(reservationKeys[2]).toBeTruthy();
  expect(reservationKeys[2]).not.toBe(reservationKeys[1]);

  await page.getByRole('button', { name: 'Continuar com a Meta' }).click();
  await page.waitForFunction(() => Boolean(window.__numberLoginCallback));
  await page.evaluate(() => { window.__oldNumberLoginCallback = window.__numberLoginCallback; });
  await page.getByRole('button', { name: 'Fechar' }).click();
  await page.evaluate(() => window.__oldNumberLoginCallback?.({ authResponse: { code: 'late-after-close' } }));
  await expect.poll(() => authorizeRequests).toBe(0);
  await page.getByRole('button', { name: 'Iniciar cadastro' }).click();
  await page.getByLabel('Business Unit').selectOption('__nova__');
  await page.getByLabel('Nome da nova Business Unit').fill('BU trocada durante popup antigo');
  await page.getByRole('button', { name: 'Reservar tentativa' }).click();
  await expect(page.getByRole('button', { name: 'Continuar com a Meta' })).toBeEnabled();
  await page.evaluate(() => window.__oldNumberLoginCallback?.({ authResponse: { code: 'late-after-bu-switch' } }));
  await expect.poll(() => authorizeRequests).toBe(0);
  expect(reservationRequests).toBe(4);
  expect(reservationKeys[3]).toBeTruthy();
  expect(reservationKeys[3]).not.toBe(reservationKeys[2]);
  expect(reservationBodies[3]).not.toBe(reservationBodies[2]);
  const finalUnits = await context.request.get(`${API}/api/bff/business-units`);
  expect(finalUnits.ok()).toBeTruthy();
  expect((await finalUnits.json() as UnitList).businessUnits).toHaveLength(beforeUnits + 2);
});

