    const conversation = await prisma.conversation.create({ data: { buId: bu.id, contact: CONTATO, contactType: 'PESSOA', status: 'QUEUED' } });
    let entered!: () => void; let release!: () => void;
    const atProvider = new Promise<void>((resolve) => { entered = resolve; });
