      await this.requireLeaseCurrent(actor, id, leaseToken);
      await this.meta.registrarNumero(body.phoneNumberId, body.pin!, token);
      const afterRegistration = await this.requireLeaseCurrent(actor, id, leaseToken);
      if (afterRegistration.version !== attempt.version + 1 || afterRegistration.stage !== 'REGISTERING') throw new ConflictException({ code: 'ATTEMPT_STALE' });
      await this.prisma.channelRegistrationAttempt.updateMany({ where: { id, stage: 'REGISTERING', version: attempt.version + 1 }, data: { stage: 'AUTHORIZED', version: { increment: 1 } } });
    } catch {
      await this.prisma.channelRegistrationAttempt.updateMany({ where: { id, stage: 'REGISTERING' }, data: { state: 'ERROR', stage: 'REGISTER_AMBIGUOUS', safeErrorCode: 'REGISTRATION_AMBIGUOUS', version: { increment: 1 } } });
      throw new ConflictException({ code: 'REGISTRATION_AMBIGUOUS' });
    }
  }
  const freshAttempt = await this.requireCurrent(actor, id);
  if (freshAttempt.sessionHash !== attempt.sessionHash || freshAttempt.stage !== 'AUTHORIZED') throw new ConflictException({ code: 'ATTEMPT_STALE' });
  await this.prisma.$transaction(async (tx) => {
    const identityRows = await tx.$queryRaw<Array<{ id: string; bu_id: string; current_channel_id: string | null; managed_lifecycle: boolean }>>`SELECT id, bu_id, current_channel_id, managed_lifecycle FROM provider_resource_identities WHERE provider = 'OFICIAL' AND external_resource_id = ${body.phoneNumberId} FOR UPDATE`;
    const mappingRow = identityRows[0];
    if (!mappingRow || mappingRow.bu_id !== attempt.buId || mappingRow.current_channel_id !== attempt.channelId) throw new ConflictException({ code: 'RESOURCE_OWNED' });
    await tx.$queryRaw`SELECT id FROM business_units WHERE id = ${attempt.buId} FOR UPDATE`;
    await tx.$queryRaw`SELECT id FROM bu_channels WHERE id = ${attempt.channelId} FOR UPDATE`;
    const channel = await tx.buChannel.findFirst({ where: { id: attempt.channelId!, currentAttemptId: id, generation: attempt.generation, operationLeaseToken: leaseToken, operationLeaseUntil: { gt: new Date() } } });
    if (!channel) throw new ConflictException({ code: 'ATTEMPT_STALE' });
    const current = await tx.channelRegistrationAttempt.findFirst({ where: { id, channelId: channel.id, generation: channel.generation } });
    if (!current || current.version !== freshAttempt.version || current.state !== 'PENDING_NUMBER' || current.stage !== 'AUTHORIZED' || current.expiresAt <= new Date()) throw new ConflictException({ code: 'ATTEMPT_STALE' });
    const bu = await tx.businessUnit.findUniqueOrThrow({ where: { id: current.buId }, select: { phone: true } });
    if (!number.telefone || bu.phone !== number.telefone) throw new ConflictException({ code: 'PHONE_MISMATCH' });
    const credentialRows = await tx.$queryRaw<Array<{ id: string; version: number }>>`SELECT id, version FROM channel_credentials WHERE channel_id = ${channel.id} FOR UPDATE`;
    const version = credentialRows[0]?.version ?? 0;
    if (version !== (activeBefore?.version ?? 0)) throw new ConflictException({ code: 'ACTIVE_CREDENTIAL_CHANGED' });
    const legacySlotPromotion = !mappingRow.managed_lifecycle && current.operation === 'REAUTORIZAR'
      && current.type === 'OFICIAL' && channel.phoneNumberId === body.phoneNumberId
      && mappingRow.current_channel_id === channel.id && credentialRows.length === 0;
    if (!mappingRow.managed_lifecycle && !legacySlotPromotion) throw new ConflictException({ code: 'RESOURCE_OWNED' });
    const nextGeneration = channel.generation + (current.operation === 'REAUTORIZAR' ? 1 : 0);
    const key = loadChannelCredentialKey(process.env);
    const plaintext = this.openCandidate(current);
    const envelope = sealChannelCredential(plaintext, key.keyId, key.key, { purpose: 'active', provider: 'OFICIAL', buId: current.buId, channelId: channel.id, generation: nextGeneration, version: version + 1 });
    const oldMappings = await tx.providerResourceIdentity.updateMany({ where: { currentChannelId: channel.id, id: { not: mappingRow.id } }, data: { currentChannelId: null, retiredAt: new Date() } });
    void oldMappings;
    const mapping = await tx.providerResourceIdentity.updateMany({
      where: { id: mappingRow.id, buId: current.buId, currentChannelId: channel.id, managedLifecycle: mappingRow.managed_lifecycle },
      data: { managedLifecycle: true, retiredAt: null, cleanupState: 'ACTIVE' },
    });
    if (!mapping.count) throw new ConflictException({ code: 'RESOURCE_OWNED' });
    const changedChannel = await tx.buChannel.updateMany({ where: { id: channel.id, currentAttemptId: id, generation: current.generation, pairingEpoch: channel.pairingEpoch, operationLeaseToken: leaseToken, operationLeaseUntil: { gt: new Date() } }, data: { generation: nextGeneration, wabaId: body.wabaId, phoneNumberId: body.phoneNumberId, ownNumberVerified: true, verifiedEpoch: channel.pairingEpoch, providerConnectionState: 'PENDING', receiptVerifiedAt: null, connectedAt: null, status: 'CONECTANDO', requiresWindow: true } });
    if (!changedChannel.count) throw new ConflictException({ code: 'ATTEMPT_STALE' });
    const credential = credentialRows[0]
      ? await tx.channelCredential.updateMany({ where: { channelId: channel.id, version }, data: { generation: nextGeneration, version: version + 1, keyId: envelope.keyId, nonce: dbBytes(envelope.nonce), ciphertext: dbBytes(envelope.ciphertext), tag: dbBytes(envelope.tag) } })
      : { count: await tx.channelCredential.create({ data: { channelId: channel.id, provider: 'OFICIAL', buId: current.buId, generation: nextGeneration, version: version + 1, keyId: envelope.keyId, nonce: dbBytes(envelope.nonce), ciphertext: dbBytes(envelope.ciphertext), tag: dbBytes(envelope.tag) } }).then(() => 1) };
    if (!credential.count) throw new ConflictException({ code: 'ACTIVE_CREDENTIAL_CHANGED' });
    const promoted = await tx.channelRegistrationAttempt.updateMany({ where: { id, version: freshAttempt.version, state: 'PENDING_NUMBER', stage: 'AUTHORIZED', generation: current.generation }, data: { generation: nextGeneration, state: 'PENDING_RECEIPT', stage: body.modoRegistro === 'NOVO' ? 'REGISTERED_PENDING_RECEIPT' : 'MAPPED_PENDING_RECEIPT', candidateKeyId: null, candidateNonce: null, candidateCiphertext: null, candidateTag: null, version: { increment: 1 } } });
    if (!promoted.count) throw new ConflictException({ code: 'ATTEMPT_STALE' });
    await this.audit(tx, actor, 'canal.onboarding.atualizado', current, body.modoRegistro === 'NOVO' ? 'REGISTERED_PENDING_RECEIPT' : 'MAPPED_PENDING_RECEIPT');
  });
  return { registration: await this.get(actor, id) };
  } finally { await this.releaseChannelLease(attempt, leaseToken); }
}

async advance(actor: RegistrationActor, id: string) { return this.runAdvance(actor, id); }
async retry(actor: RegistrationActor, id: string) {
  const attempt = await this.requireCurrent(actor, id, undefined, true);
  if (attempt.stage.endsWith('_AMBIGUOUS') || attempt.stage === 'SUBSCRIBING') throw new ConflictException({ code: 'MANUAL_RECOVERY_REQUIRED' });
  return this.runAdvance(actor, id);
}

async cancel(actor: RegistrationActor, id: string) {
  const attempt = await this.requireCurrent(actor, id, undefined, true);
  if (attempt.state === 'CONNECTED') throw new ConflictException({ code: 'ATTEMPT_ALREADY_CONNECTED' });
